use serde::Deserialize;

#[derive(Deserialize, Debug)]
struct User {
    name: String,
    age: u32,
}

fn main() {
    let user: User = serde_json::from_str(r#"{"name":"Ann","age":41}"#).unwrap();
    println!("{:?}", user);
}

package main

import (
	"encoding/json"
	"fmt"
)

type User struct {
	Name string `json:"name"`
	Age  int    `json:"age"`
}

func main() {
	var u User
	if err := json.Unmarshal([]byte(`{"name":"Ann","age":41}`), &u); err != nil {
		panic(err)
	}
	fmt.Println(u.Name)
}

def greet(name: str) -> str:
